#!/usr/bin/env bash
set -euo pipefail
[[ -d .git && -f pubspec.yaml && -f desktop/hyper_player/VISUAL_ALIGNMENT_8.md ]] || { echo 'Run in your repository root after the eighth Android visual-alignment update.' >&2; exit 1; }
python3 - <<'VISUAL_GROUP_NINE'
from pathlib import Path
import base64
files = {
'desktop/hyper_player/lib/main.dart': '',
'desktop/hyper_player/lib/screens/video_adjustment_sheets.dart': '',
'desktop/hyper_player/test/video_adjustment_test.dart': '',
'desktop/hyper_player/VISUAL_ALIGNMENT_9.md': '',
}
for name, data in files.items():
    p = Path(name)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(base64.b64decode(data))
print('Android-style Video fit and Subtitle delay panels installed. Android unchanged.')
VISUAL_GROUP_NINE
